INSERT INTO `full_text` VALUES (1,'Delivery Tool contains delivery builders.'),(548,'Order Tool contains order builders.'),(750,'erp5_full_text_mroonga_catalog This business template contains SQL methods etc. to use a mroonga table as a fulltext storage.'),(766,'Field Library for Categories'),(773,'Obsoleted by Default Field Library for Reports'),(830,'Default Field Library'),(845,'Obsoleted by Default Field Library for Dialogs'),(848,'Deprecated (Use Default Field Library instead)'),(851,'erp5_core_proxy_field_legacy This bt must be dropped as soon as cleanup is finished.\n\nThis bt contains for compatibility reasons all old not well named proxy field and proxy field libraries that were in erp5_core before. Like this we can do cleanup of erp5_core but we still give more time to people still using old fields to do the cleanup.'),(901,'Local Roles'),(908,'Telephone Coordinate'),(915,'Default FAX Coordinate'),(917,'Change Function'),(938,'Default Field Library'),(971,'Bank Account Field Library'),(991,'Bank Account'),(1002,'Assignment Field Library'),(1015,'Assignment'),(1018,'Import Signature'),(1020,'Full Size Image'),(1031,'Agent'),(1038,'Agent Privilege'),(1043,'Address Field Library'),(1045,'Persistent Memcached'),(1046,'Image by mimetype'),(1047,'Image by extension'),(1048,'Quantity'),(1049,'Property'),(1050,'Category'),(1051,'Line'),(1052,'Delivery'),(1053,'Cell'),(1054,'Volatile Cache Plugin'),(1055,'Documents Cache'),(1056,'Migration to Embedded File portal type This alarm when triggered will migrate all embedded \"File\" and \"Image\" objects to an unified \"Embedded File\".'),(1057,'Queries'),(1058,'Persons'),(1059,'Notification Messages'),(1060,'Currencies'),(1061,'Organisations'),(1062,'Use Defines resources utilisation in system, allows to\ndistinguish resources by its usage - sell able, purchasable, taxes,\ndiscount, any other special utilisation.'),(1063,'Update Frequency'),(1064,'Trade Phase'),(1065,'Successor'),(1066,'Subordination'),(1067,'Source Region A virtual Category which allows to access the region of section value of a Movement as if it were a category.'),(1068,'Source Referral'),(1069,'Source Carrier'),(1070,'Solver'),(1071,'Social Title'),(1072,'Social Form'),(1073,'Skill'),(1074,'Site'),(1075,'Salary level'),(1076,'Role'),(1077,'Resource Use'),(1078,'Region'),(1079,'Property Mapping'),(1080,'Price Currency'),(1081,'Predecessor'),(1082,'Payment Mode'),(1083,'Order Builder'),(1084,'Natural Parent This base category is used to define the blood relation between one person and another'),(1085,'Nationality'),(1086,'Market Segment A Market segment is a subgroup of people or organizations sharing one or more characteristics that cause them to have similar product needs.'),(1087,'Marital Status'),(1088,'Legal Parent This base category is used to define the legal parents (as opposed to blood relation) of a Person'),(1089,'Ledger Ledger is used to split movements, deliveries, or orders of the same type in different subsets'),(1090,'Insurance Coverage This base category defines the insurance coverage of a Person or Organisation. A Person can be covered by the insurance of another Person and/or and Insurance contract directly.'),(1091,'Group Group define the corporate group and the business unit structure. Group is acquired through careers and subordination.'),(1092,'Grade Grade is like a job classification on which the employee pay is determined. It\'s also similar to military grade.'),(1093,'Gender'),(1094,'Function Function correspond to the task you do day by day.'),(1095,'Follow Up'),(1096,'End Of End of what to wait...'),(1097,'Economical Class'),(1098,'Divergence Scope'),(1099,'Destination Region A virtual Category which allows to access the region of destination value of a Movement as if it were a category.'),(1100,'Destination Referral'),(1101,'Destination Carrier'),(1102,'Delivery Solver'),(1103,'Delivery Builder'),(1104,'Currency Exchange Type'),(1105,'Creator'),(1106,'Contributor'),(1107,'Conflicting Solver'),(1108,'Collect Order Group This category is used for Movement Groups in Builders.'),(1109,'Bank Account Type This category represents bank account type such as saving account, checking account, etc.'),(1110,'Agent Privilege'),(1111,'Agent'),(1112,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.\n\n  This movement group is used to group movements that have the same\n  variation property dict.'),(1113,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.'),(1114,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.'),(1115,'A Telephone object can contain a telephone number.'),(1116,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.'),(1117,'Solver Tool contains Solver Types'),(1118,'Rounding Tool'),(1120,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.'),(1121,'A Role Definition allows for associating a certain Zope role to a list of users, organisations, domains, etc.'),(1122,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.'),(1124,'A Query allows for capturing questions of users about ERP5 documents. It can be used as a collaboration tool, for sharing knowledge or to provide online help.'),(1125,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.'),(1126,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.'),(1127,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.'),(1128,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.'),(1129,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.'),(1130,'Holds person objects'),(1131,'Persons capture the contact information (ex. name, phone number) and the relation between entities (ex. who is assigned to which function and which organisation). Persons are supported by a standard validation workflow.'),(1132,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.'),(1133,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.'),(1134,'Holds organisation objects'),(1135,'Organisations capture the contact information (ex. name, phone number) and their classification (ex. site, group, function etc.). Organisations are supported by a standard validation workflow.'),(1137,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.'),(1138,'Delivery Builder objects allow to gather multiple Simulation Movements\n    into a single Delivery. \n\n    The initial quantity property of the Delivery Line is calculated by\n    summing quantities of related Simulation Movements.\n\n    Delivery Builders are called for example whenever an order is confirmed.\n    They are also called globaly in order to gather any confirmed or above \n    Simulation Movement which was not associated to any Delivery Line. \n    Such movements are called orphaned Simulation Movements.\n\n    Delivery Builder objects are provided with a set a parameters to achieve \n    their goal:\n\n    A path definition: source, destination, etc. which defines the general \n    kind of movements it applies.\n\n    simulation_select_method which defines how to query all Simulation \n    Movements which meet certain criteria (including the above path path \n    definition).\n\n    collect_order_list which defines how to group selected movements \n    according to gathering rules.\n\n    delivery_select_method which defines how to select existing Delivery \n    which may eventually be updated with selected simulation movements.\n\n    delivery_module, delivery_type and delivery_line_type which define the \n    module and portal types for newly built Deliveries and Delivery Lines.\n\n    Delivery Builders can also be provided with optional parameters to \n    restrict selection to a given root Applied Rule caused by a single Order\n    or to Simulation Movements related to a limited set of existing \n    Deliveries.'),(1141,'Messages that can be seen by the user and that appear depending upon the actions of the user. They can be warning, information or error messages'),(1142,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.'),(1143,'This movement group gathers movements which their start_date and stop_date are in the same month.'),(1144,'Mapped Property object describes how properties or categories are mapped from simulation movements to delivery documents, eg. use source as destination, use destination as source, use quantity as -quantity, etc.'),(1145,'A URL allows to represent in a standard way coordinates such as web sites, emails, ftp sites, etc.'),(1146,'This movement group is used to collect movements related to the same invoice. This movement group should be used in delivery level.'),(1147,'Image type documents in ERP5. Many formats are supported'),(1148,'A Geographical Location represent a point on the surface of the Earth which is address by its coordinates. Geographical Location'),(1149,'A Geographical Area represent an area of the Earth which is address by its Geographical Points. Geographical Area'),(1150,'A file, in its widest sense'),(1151,'A fax number that can be stored on a person or organisation document'),(1153,'Holds Embedded File. Embedded Folder'),(1154,'An embedded file (which can act as an image as well). Embedded File'),(1155,'An Email object can contain a link to an online resource.'),(1157,'Delivery Type is a Base Type which allows its portal type instances to define a list of ledger to which they can belong to. Delivery Type'),(1160,'Like CausalityAssignmentMovementGroup, but using the delivery relation of\nsimulation movements instead of order relation. This is intended to be used in deeper level of simulation tree.'),(1161,'XXX Deprecated. It must be deleted. 2 new portal types replace it: Generated Delivery Builder and Simulated Delivery Builder\n\nDelivery Builder objects allow to gather multiple Simulation Movements into\na single Delivery. The initial quantity property of the Delivery Line is\ncalculated by summing quantities of related Simulation Movements.\n\nDelivery Builders are called for example whenever an order is confirmed.\nThey are also called globally in order to gather any confirmed or above\nSimulation Movement which was not associated to any Delivery Line.  Such\nmovements are called orphaned Simulation Movements.\n\nDelivery Builder objects are provided with a set a parameters to achieve\ntheir goal:\n\nA path definition: source, destination, etc. which defines the general\nkind of movements it applies.\n\nsimulation_select_method which defines how to query all Simulation\nMovements which meet certain criteria (including the above path path\ndefinition).\n\ncollect_order_list which defines how to group selected movements according\nto gathering rules.\n\ndelivery_select_method which defines how to select existing Delivery  which\nmay eventually be updated with selected simulation movements.\n\ndelivery_module, delivery_type and delivery_line_type which define the\nmodule and portal types for newly built Deliveries and Delivery Lines.\n\nDelivery Builders can also be provided with optional parameters to\nrestrict selection to a given root Applied Rule caused by a single Order or\nto Simulation Movements related to a limited set of existing Deliveries.'),(1162,'This movement group is used to group movements which belong to the same day'),(1163,'Holds Accounting Transaction objects'),(1164,'This line can define the value of a currency towards another currency'),(1165,'Une ligne tarifaire.'),(1166,'A Currency is a resource which can be credited or debited on general ledger accounts. It defines currency information, identification and exchange rates to one or multiple reference currencies.'),(1167,'A credit registered in a bank and that can be used for a payment'),(1168,'A chat address is an identifier in an Instant Messaging service.'),(1169,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.'),(1170,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.'),(1171,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.'),(1172,'A step in the career of a person.'),(1173,'The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.'),(1174,'A bank account number holds a collection of numbers and codes (ex. SWIFT, RIB, etc.) which may be used to identify a bank account. It is owned by a Person or an Organisation. A Bank Account contains Agents with Agent Privileges used by the owner to delegate the management of the bank account to trusted third-party Persons.\n\nBankAccount inherits from Base and from the mix-in Coordinate.'),(1175,'An Assignment allows a person to be assigned to an organisation during a period without changing his career organisation.'),(1176,'An Agent Privilege allows the Bank Account owner to give permissions to an Agent for a given period of time, for a maximum amount of money.'),(1